; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: test (Test harness (port I/O console)), starts in normal mode
; ============================================================

			org #4000

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)

ntc_start:
			di
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:

			; 3: n = 1000
			dw kw_ltov, 1000, var_n

			; 4: For i = 2 To n : s(i) = 1 : Next
			dw kw_ltov, 2, var_i
			dw kw_vtov, var_n, for1_l
			dw kw_forupv_n, var_i, for1_l, for1_e
for1_t:
			dw kw_asetl, arr_s, var_i, 1
			dw kw_next1v_n, var_i, for1_l, for1_t
for1_e:

			; 5: i = 2
			dw kw_ltov, 2, var_i

			; 6: While i * i <= n
			dw wh2_c_go
wh2_t:

			; 7: If s(i) Then
			dw kw_aget, arr_s, var_i, tmp0
			dw kw_goto_ifzero_n, tmp0, if3_1

			; 8: For j = i * i To n Step i : s(j) = 0 : Next
			dw kw_mulvv, var_i, var_i, var_j
			dw kw_vtov, var_n, for4_l
			dw kw_vtov, var_i, for4_s
			dw kw_forentry_n, var_j, for4_s, for4_l, for4_e
for4_t:
			dw kw_asetl, arr_s, var_j, 0
			dw kw_fornext_n, var_j, for4_s, for4_l, for4_t
for4_e:

			; 9: End If
if3_1:

			; 10: i = i + 1
			dw kw_inc, var_i

			; 11: Wend
wh2_c:
			dw kw_mulvv, var_i, var_i, tmp0
			dw kw_scplevv, tmp0, var_n
			dw kw_goto_iftrue_n, wh2_t
wh2_e:

			; 12: c = 0
			dw kw_ztov, var_c

			; 13: For i = 2 To n
			dw kw_ltov, 2, var_i
			dw kw_vtov, var_n, for5_l
			dw kw_forupv_n, var_i, for5_l, for5_e
for5_t:

			; 14: If s(i) Then Print i; " "; : c = c + 1
			dw kw_aget, arr_s, var_i, tmp0
			dw kw_goto_ifzero_n, tmp0, if6_1
			dw kw_printint, var_i
			dw kw_printstrvar, str0
			dw kw_inc, var_c
if6_1:

			; 15: Next
			dw kw_next1v_n, var_i, for5_l, for5_t
for5_e:

			; 16: Print : Print c; " primes"
			dw kw_printnl
			dw kw_printint, var_c
			dw kw_printstrvar, str1
			dw kw_printnl

			; 17: Print "Press a key";
			dw kw_printstrvar, str2

			; 18: Do : Frame : Loop Until Inkey <> 0
do7_t:
			dw kw_frame
			dw kw_inkey, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse_n, do7_t
do7_e:

			; 19: Print
			dw kw_printnl

			; 20: End
			dw kw_stop

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

wh2_c_go:			ld sp, wh2_c
			jp ntc_xn

; ============================================================
; Variables
; ============================================================

arr_s:			ds 2002		; 1001 words
var_n:			dw 0
var_i:			dw 0
for1_l:			dw 0
var_j:			dw 0
for4_l:			dw 0
for4_s:			dw 0
var_c:			dw 0
for5_l:			dw 0
tmp0:			dw 0

; ============================================================
; Strings
; ============================================================

str0:			db " ", 0
str1:			db " primes", 0
str2:			db "Press a key", 0

; ============================================================
; Keyword library (used)
; ============================================================

;## ntc_data @shared
; ------------------------------------------------------------
; Scratch space
; ------------------------------------------------------------
ntc_next:		ret				; IX target that continues the thread
ntc_csp:		dw 0			; caller SP, for kw_stop (and the normal mode stack)
ntc_ip:			dw 0			; normal mode: thread position while out of the thread
ntc_ticks:		dw 0			; interrupt count (normal mode, platform handler)
ntc_gnlo:		db 0			; ntc_getn: low byte
ntc_nmode:		db 0			; 1 = running in normal mode (waits let interrupts in)
ntc_mode:		db 0			; div mode 0=quotient 1=remainder
ntc_sgnq:		db 0			; quotient sign (bit 7)
ntc_sgnr:		db 0			; remainder sign (bit 7)
ntc_lead:		db 0			; printint: digit seen
ntc_icnt:		db 0			; gets: chars typed
ntc_icap:		db 0			; gets: the buffer's capacity
ntc_sptr:		dw 0			; printbuf: text pointer
ntc_iptr:		dw 0			; gets: buffer pointer
ntc_ilink:		dw 0			; gets: where to go when done
ntc_ivar:		dw 0			; inputint / inkey: dest var
ntc_aptr:		dw 0			; atoi: text pointer
ntc_hookon:		db 0			; 1 = the Interrupt hook may run (set, and not running now)
ntc_hookset:	db 0			; 1 = an Interrupt hook is set
ntc_hookpend:	db 0			; 1 = an interrupt came, the hook runs at the next safe point
ntc_hook:		dw 0			; the hook Sub's call stub
ntc_hostix:		dw 0			; host platforms: IX kept over a firmware / BDOS call
ntc_numbuf:		ds 14			; printint / long print: digits (+ spaces for Option VBPrint)
				db 40			; ntc_inbuf's capacity (as every string variable has)
ntc_inbuf:		ds 41			; inputint: typed text

;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			ld ix, ntc_stop_back
			jp ntc_plat_exit
ntc_stop_back:
			ld sp, (ntc_csp)
			ei
			ret

;## ntc_xn ntc_data @shared
; normal mode "next": every normal mode keyword ends here (its ret
; became jp ntc_xn). Thread position to ntc_ip, real stack, one
; instruction with interrupts on, then back into the thread.
ntc_xn:
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
			nop					; an interrupt can be taken here
			di
			ld sp, (ntc_ip)
			ret

;## kw_goto_iffalse (normal mode copy)
;kw_goto_iffalse, <label>  - branch if NZ (false)
kw_goto_iffalse_n:
			pop hl
			jp z, ntc_xn
			ld sp, hl
			jp ntc_xn

;## kw_goto_iftrue (normal mode copy)
;kw_goto_iftrue, <label>  - branch if Z (true)
kw_goto_iftrue_n:
			pop hl
			jp nz, ntc_xn
			ld sp, hl
			jp ntc_xn

;## kw_goto_ifzero (normal mode copy)
;kw_goto_ifzero, <var>, <label>  - branch if var = 0
kw_goto_ifzero_n:
			pop hl
			ld a, (hl)
			inc hl
			or (hl)
			pop hl
			jp nz, ntc_xn
			ld sp, hl
			jp ntc_xn

;## ntc_for_jump (normal mode copy)
; tails for the FOR / NEXT keywords. DE = var value, HL = limit,
; SP = thread at the label word. Signed compare by flipping bit 15.
; ntc_for_gt: jump to the label if var > limit, else skip it
ntc_for_gt_n:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			or a
			sbc hl, de			; limit - var, carry = var > limit
			pop hl
			jp nc, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_lt: jump to the label if var < limit, else skip it
ntc_for_lt_n:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			ex de, hl
			or a
			sbc hl, de			; var - limit, carry = var < limit
			pop hl
			jp nc, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_le: jump to the label if var <= limit (loop again)
ntc_for_le_n:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			or a
			sbc hl, de			; limit - var, no carry = var <= limit
			pop hl
			jp c, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_ge: jump to the label if var >= limit (loop again)
ntc_for_ge_n:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			ex de, hl
			or a
			sbc hl, de			; var - limit, no carry = var >= limit
			pop hl
			jp c, ntc_xn
			ld sp, hl
			jp ntc_xn

;## kw_forupv (normal mode copy) ntc_for_jump
;kw_forupv, <var>, <limit var>, <endlabel>
kw_forupv_n:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			jp ntc_for_gt_n

;## kw_next1v (normal mode copy) ntc_for_jump
;kw_next1v, <var>, <limit var>, <toplabel>
kw_next1v_n:
			pop hl
			inc (hl)
			ld e, (hl)
			inc hl
			jr nz, ntc_n1v_nc_n
			inc (hl)
ntc_n1v_nc_n:
			ld d, (hl)
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			jp ntc_for_le_n

;## kw_forentry (normal mode copy)
;kw_forentry, <var>, <stepvar>, <limvar>, <endlabel>
;  skip the loop if var is already past lim for the step sign
kw_forentry_n:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld b, (hl)
			inc hl
			ld b, (hl)
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			bit 7, b
			jr nz, ntc_fe_neg_n
			or a
			sbc hl, de
			pop hl
			jp nc, ntc_xn
			ld sp, hl
			jp ntc_xn
ntc_fe_neg_n:
			ex de, hl
			or a
			sbc hl, de
			pop hl
			jp nc, ntc_xn
			ld sp, hl
			jp ntc_xn

;## kw_fornext (normal mode copy)
;kw_fornext, <var>, <stepvar>, <limvar>, <toplabel>
;  var += step, loop back while var has not passed lim
kw_fornext_n:
			pop ix
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld l, (ix+0)
			ld h, (ix+1)
			add hl, de
			ld (ix+0), l
			ld (ix+1), h
			ld b, d
			ex de, hl
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			bit 7, b
			jr nz, ntc_fn_neg_n
			or a
			sbc hl, de
			pop hl
			jp c, ntc_xn
			ld sp, hl
			jp ntc_xn
ntc_fn_neg_n:
			ex de, hl
			or a
			sbc hl, de
			pop hl
			jp c, ntc_xn
			ld sp, hl
			jp ntc_xn

; ============================================================
; Assignment
; ============================================================

;## kw_ltov
;kw_ltov, <literal>, <destvar>
kw_ltov:
			pop de
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_vtov
;kw_vtov, <sourcevar>, <destvar>
kw_vtov:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_ztov
;kw_ztov, <destvar>
kw_ztov:
			xor a
			pop hl
			ld (hl), a
			inc hl
			ld (hl), a
			ret

;## kw_inc
;kw_inc, <var>
kw_inc:
			pop hl
			inc (hl)
			ret nz
			inc hl
			inc (hl)
			ret

;## ntc_mul
; BC * DE -> pop destvar, store. Low 16 bits (same signed/unsigned)
ntc_mul:
			ld hl, 0
			ld a, 16
ntc_mul_loop:
			add hl, hl
			sla e
			rl d
			jr nc, ntc_mul_skip
			add hl, bc
ntc_mul_skip:
			dec a
			jr nz, ntc_mul_loop
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_mulvv ntc_mul
;kw_mulvv, <var1>, <var2>, <destvar>
kw_mulvv:
			pop hl
			ld c, (hl)
			inc hl
			ld b, (hl)
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			jp ntc_mul

;## ntc_cmp
ntc_cmp_slt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ult:
			ex de, hl
			or a
			sbc hl, de
			sbc a, a
			inc a
			ret
ntc_cmp_sge:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_uge:
			ex de, hl
			or a
			sbc hl, de
			sbc a, a
			ret
ntc_cmp_sgt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ugt:
			or a
			sbc hl, de
			sbc a, a
			inc a
			ret
ntc_cmp_sle:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ule:
			or a
			sbc hl, de
			sbc a, a
			ret
ntc_cmp_eq:
			or a
			sbc hl, de
			ret
ntc_cmp_ne:
			or a
			sbc hl, de
			jr z, ntc_cmp_ne_f
			xor a
			ret
ntc_cmp_ne_f:
			or 1
			ret

;## kw_scplevv ntc_cmp
kw_scplevv:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			jp ntc_cmp_sle

;## kw_cpnevl ntc_cmp
kw_cpnevl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			jp ntc_cmp_ne

; ============================================================
; Memory (PEEK / POKE / DEEK / DOKE)
; ============================================================

;## kw_aget
;kw_aget, <arraybase>, <indexvar>, <destvar>
kw_aget:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, hl
			add hl, de
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_asetl
;kw_asetl, <arraybase>, <indexvar>, <literal>
kw_asetl:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, hl
			add hl, de
			pop bc
			ld (hl), c
			inc hl
			ld (hl), b
			ret

; ============================================================
; Random (16 bit xorshift 7,9,8 - period 65535)
; ============================================================

;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated ASCII text at (ntc_sptr), then ret (thread)
ntc_printbuf:
			ld hl, (ntc_sptr)
			ld a, (hl)
			or a
			ret z
			inc hl
			ld (ntc_sptr), hl
			ld ix, ntc_printbuf
			jp ntc_plat_putc

;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			pop hl
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## ntc_itoa ntc_data
; HL = signed value, DE = buffer: writes the digits and a 0 (DE ends on
; the 0). jp (ix) back. Uses A, BC, IY.
ntc_itoa:
			bit 7, h
			jr z, ntc_ia_pos
			ld a, '-'
			ld (de), a
			inc de
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_ia_pos:
			xor a
			ld (ntc_lead), a
			ld iy, ntc_pow10
ntc_ia_pow:
			ld c, (iy+0)
			ld b, (iy+1)
			ld a, b
			or c
			jr z, ntc_ia_last
			ld a, '0' - 1
ntc_ia_sub:
			inc a
			and a
			sbc hl, bc
			jr nc, ntc_ia_sub
			add hl, bc
			cp '0'
			jr nz, ntc_ia_out
			ld b, a
			ld a, (ntc_lead)
			or a
			ld a, b
			jr z, ntc_ia_skip
ntc_ia_out:
			ld (de), a
			inc de
			ld a, 1
			ld (ntc_lead), a
ntc_ia_skip:
			inc iy
			inc iy
			jr ntc_ia_pow
ntc_ia_last:
			ld a, l
			add a, '0'
			ld (de), a
			inc de
			xor a
			ld (de), a
			jp (ix)
ntc_pow10:		dw 10000, 1000, 100, 10, 0

;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld de, ntc_numbuf
			ld ix, ntc_pi_done
			jp ntc_itoa
ntc_pi_done:
			ld hl, ntc_numbuf
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## kw_printnl ntc_data ntc_plat_screen
;kw_printnl
kw_printnl:
			ld ix, ntc_next
			jp ntc_plat_newline

;## kw_inkey ntc_data ntc_plat_key
;kw_inkey, <destvar>  - new key press or 0, no wait
kw_inkey:
			pop hl
			ld (ntc_ivar), hl
			ld ix, ntc_inkey_got
			jp ntc_plat_scankey
ntc_inkey_got:
			ld hl, (ntc_ivar)
			ld (hl), a
			inc hl
			ld (hl), 0
			ret

;## kw_frame ntc_data ntc_plat_frame
;kw_frame  - wait for the start of the next frame flyback
kw_frame:
			ld ix, ntc_next
			jp ntc_plat_frame

;## ntc_plat_data
ntc_curx:		db 0			; cursor column (0 based)
ntc_cury:		db 0			; cursor row (0 based)
ntc_scols:		db 40			; columns in this mode
ntc_srows:		db 25			; rows
ntc_wrapped:	db 0			; 1 = the last character wrapped to the next line

;## ntc_plat_screen ntc_plat_data ntc_data
; ntc_plat_putc - A = character: out, move on, new line after the last column
ntc_plat_putc:
			out (#fe), a
			ld a, (ntc_scols)
			ld b, a
			ld a, (ntc_curx)
			inc a
			ld (ntc_curx), a
			cp b
			jr z, ntc_pc_wrap
			xor a
			ld (ntc_wrapped), a
			jp (ix)
ntc_pc_wrap:
			ld a, 1				; wrapped: a new line straight after does nothing
			ld (ntc_wrapped), a
			jr ntc_nl_do

; ntc_plat_newline - column 0, next row (the harness scrolls); nothing straight after a wrap
ntc_plat_newline:
			ld a, (ntc_wrapped)
			or a
			jr z, ntc_nl_do
			xor a
			ld (ntc_wrapped), a
			jp (ix)
ntc_nl_do:
			out (#f9), a
			xor a
			ld (ntc_curx), a
			ld a, (ntc_cury)
			inc a
			cp 25
			jr c, ntc_nl_row
			ld a, 24
ntc_nl_row:
			ld (ntc_cury), a
			jp (ix)

; ntc_plat_backspace - back one and blank that cell
ntc_plat_backspace:
			xor a
			ld (ntc_wrapped), a
			ld a, (ntc_curx)
			or a
			jr nz, ntc_bs_col
			ld a, (ntc_cury)
			or a
			jr z, ntc_bs_none
			dec a
			ld (ntc_cury), a
			ld a, (ntc_scols)
ntc_bs_col:
			dec a
			ld (ntc_curx), a
			out (#f5), a
ntc_bs_none:
			jp (ix)

; ntc_plat_cls - clear, cursor home
ntc_plat_cls:
			out (#fc), a
			xor a
			ld (ntc_wrapped), a
			ld (ntc_curx), a
			ld (ntc_cury), a
			jp (ix)

; ntc_plat_mode - A = mode 0-2 (3 = 2): columns, clear
ntc_plat_mode:
			cp 3
			jr c, ntc_md_ok
			ld a, 2
ntc_md_ok:
			out (#fa), a
			ld b, 20
			or a
			jr z, ntc_md_set
			ld b, 40
			dec a
			jr z, ntc_md_set
			ld b, 80
ntc_md_set:
			ld a, b
			ld (ntc_scols), a
			jr ntc_plat_cls

; ntc_plat_locate - H = column, L = row, 1 based, kept on screen
ntc_plat_locate:
			xor a
			ld (ntc_wrapped), a
			ld a, h
			or a
			jr z, ntc_lc_x0
			dec a
ntc_lc_x0:
			ld c, a
			ld a, (ntc_scols)
			dec a
			cp c
			jr c, ntc_lc_xmax
			ld a, c
ntc_lc_xmax:
			ld (ntc_curx), a
			ld a, l
			or a
			jr z, ntc_lc_y0
			dec a
ntc_lc_y0:
			cp 25
			jr c, ntc_lc_ymax
			ld a, 24
ntc_lc_ymax:
			ld (ntc_cury), a
			ld a, (ntc_curx)
			inc a
			out (#fb), a
			ld a, (ntc_cury)
			inc a
			out (#fb), a
			jp (ix)

;## ntc_plat_key ntc_data
; ntc_plat_scankey - A = key pressed or 0
ntc_plat_scankey:
			in a, (#f8)
			jp (ix)

; ntc_plat_getkey - wait for a key, A = key
ntc_plat_getkey:
			in a, (#fd)
			jp (ix)

;## ntc_plat_frame
ntc_plat_frame:
			jp (ix)

;## ntc_plat_exit ntc_plat_data
ntc_plat_exit:
			jp (ix)


ntc_end:				; the end of the program
